/**
 * The figures each person on a sheet shows — what they have claimed (their OPEN, PENDING and SETTLED
 * claims, leaving out the OPEN and PENDING ones dated within one of their holds that no statement binds)
 * and their due-total (the sum of what is due on those claims as each shows it, n/a when none has a figure and no rate of
 * their grade is in force on the sheet's today, and at most the sheet's cap in force on its today when it has one) and their
 * overdue-total (the sum of what is due on those that are OPEN or PENDING and past their due-by on the
 * sheet's today, as each shows it) — and the sheet's totals of them. A change that moves
 * any of them is followed in the audit by a ROLLUP line per person whose figures moved, then a TOTALS
 * line when the sheet's totals moved: take a {@link #snapshot} before the change, and
 * {@link #recordSince} it after the change has recorded its own lines.
 */
@Service
public class RollupService {

    /** A due-total shown when there is none. */
    public static final String NONE = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final DatedSettings dated;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, DatedSettings dated, Audit audit) {
        this.dated = dated;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** A person's figures, as shown. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    /** The figures the sheet shows now. */
    @Transactional(propagation = Propagation.MANDATORY)
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        BigDecimal cap = sheet == null ? null : dated.cap(sheetId);
        List<Claim> all = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        BigDecimal overdueTotal = zero();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean any = false;
            for (Claim claim : all) {
                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person, today)) continue;
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = shownOf(claim, person);
                if (figure == null) continue;
                if (isOverdue(claim, today)) overdue = overdue.add(figure);
                due = due.add(figure);
                any = true;
            }
            due = cappedOf(due, cap);
            boolean rated = today != null && rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
            claimedTotal = claimedTotal.add(claimed);
            overdueTotal = overdueTotal.add(overdue);
            if (any || rated) dueTotal = dueTotal.add(due);
            figures.put(person.getId(), new Figures(person.getName(), text(claimed), any || rated ? text(due) : NONE,
                    text(overdue)));
        }
        return new Snapshot(figures, text(claimedTotal), text(dueTotal), text(overdueTotal));
    }

    /** Record the ROLLUP and TOTALS lines for the figures that moved since {@code before}. */
    @Transactional(propagation = Propagation.MANDATORY)
    public void recordSince(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        after.people().forEach((id, now) -> {
            Figures then = before.people().get(id);
            if (then != null && then.claimed().equals(now.claimed()) && then.dueTotal().equals(now.dueTotal())
                    && then.overdueTotal().equals(now.overdueTotal())) return;
            audit.change("ROLLUP", sheetId, user, "person=" + now.name(), "claimed=" + now.claimed(),
                    "due-total=" + now.dueTotal(), "overdue-total=" + now.overdueTotal());
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())
                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
            audit.change("TOTALS", sheetId, user, "claimed-total=" + after.claimedTotal(),
                    "due-total=" + after.dueTotal(), "overdue-total=" + after.overdueTotal());
        }
    }

    /** Whether the claim is overdue: OPEN or PENDING, not deferred on the sheet's {@code today}, and due
     * by a date before it. */
    public static boolean isOverdue(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
                && !claim.isDeferredOn(today) && claim.getDueBy().isBefore(today);
    }

    /** A due-total as shown: at most {@code cap}, when there is one. */
    public static BigDecimal cappedOf(BigDecimal due, BigDecimal cap) {
        return cap == null ? due : due.min(cap);
    }

    /** Whether the claim counts in the live totals on the sheet's {@code today}: OPEN, PENDING or
     * SETTLED, but not an OPEN claim deferred on {@code today}, nor OPEN or PENDING when it is dated
     * within one of its person's holds and no statement binds it (a PENDING claim is bound by none while
     * it is). */
    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
        if (!claim.getStatus().counts()) return false;
        if (!claim.getStatus().isOpen()) return true;
        if (claim.isDeferredOn(today)) return false;
        boolean bound = claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
        return bound || !person.isHeldOn(claim.getDate());
    }

    /** The figure the claim shows and totals now: what was fixed when it was settled at a rate;
     * otherwise, unless it is PENDING (which no statement binds while it is), the figure a statement
     * bound it to; otherwise what is due on it at its person's rate.
     * Null when it has no figure. */
    public BigDecimal figureOf(Claim claim, Person person) {
        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
        return dueOf(claim, person);
    }

    /** What is due on the claim as it shows and totals now: its figure, plus its late charge; null when
     * it has no figure. */
    public BigDecimal shownOf(Claim claim, Person person) {
        BigDecimal figure = figureOf(claim, person);
        return figure == null ? null : figure.add(lateChargeOf(claim, figure));
    }

    /** The late charge on an OPEN or PENDING claim whose figure is {@code figure}: the sheet's late percent in force on the claim's date of that
     * figure for every full 30 days the claim is overdue (past its due-by, fixed when it was added, on
     * the sheet's today), rounded to two decimals as the claim rounds (see {@link #roundingOf}); 0.00 on a claim not OPEN or
     * PENDING, or not overdue (a deferred claim is not), and on a correction. A statement never binds it: it follows the sheet's today until the claim is settled. */
    public BigDecimal lateChargeOf(Claim claim, BigDecimal figure) {
        if (!claim.getStatus().isOpen()) return zero();
        return overdueChargeOf(claim, figure);
    }

    /** What would be due on the claim now were it an OPEN claim bound by no statement: its due at its
     * person's rate (see {@link #dueOf}) plus the late charge it would have then; null when it would
     * have no figure. */
    public BigDecimal openShownOf(Claim claim, Person person) {
        BigDecimal figure = dueOf(claim, person);
        return figure == null ? null : figure.add(overdueChargeOf(claim, figure));
    }

    /** The late charge on a claim whose figure is {@code figure}, whatever its status (see {@link #lateChargeOf}). */
    private BigDecimal overdueChargeOf(Claim claim, BigDecimal figure) {
        if (claim.isCorrection()) return zero();
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        if (sheet == null || claim.isDeferredOn(sheet.getToday())) return zero();
        long periods = Math.max(0, ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday())) / 30;
        return figure.multiply(dated.latePctOn(sheet.getId(), claim.getDate())).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, roundingOf(claim, sheet));
    }

    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
     * divided by 100, rounded to two decimals as the claim rounds (see {@link #roundingOf}), and at least the sheet's floor in force on the claim's date (a correction,
     * whose due is negative, has no floor); null when no
     * rate of the grade in force for them on the claim's date applies then. */
    public BigDecimal dueOf(Claim claim, Person person) {
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        BigDecimal floor = sheet == null ? zero() : dated.floorOn(sheet.getId(), claim.getDate());
        RoundingMode rounding = roundingOf(claim, sheet);
        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
                .map(due -> claim.isCorrection() ? due : due.max(floor))
                .orElse(null);
    }

    /** How the claim's live figures round: half up when it is dated before the sheet's policy date in
     * force, half to even when on or after it. A correction rounds by the date of the claim it corrects. */
    public RoundingMode roundingOf(Claim claim, Sheet sheet) {
        if (sheet == null) return RoundingMode.HALF_EVEN;
        LocalDate dated = claim.getDate();
        if (claim.isCorrection() && claim.getCorrects() != null) {
            dated = claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
                    .map(Claim::getDate).orElse(dated);
        }
        return dated.isBefore(sheet.policyDateInForce()) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String text(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** A sheet's settings: the role each user name has on it (a clerk unless made a steward) and its clerk
 * limit, the most a clerk may settle a claim for (none when null), and its floor, the least a claim's
 * live due can be, and its cap, the most a person's due-total can be (none when null), and its terms, how many days after its date a claim is due by (each grade may have its own
 * terms in their place), and its late percent, the
 * percent of its figure an overdue claim's due gains for every full 30 days it is overdue, and its policy
 * date, which decides how a claim's live figures round (the sheet's today when none is set), and its
 * period numbering from, the date from which a claim opened is numbered within its period (off when null).
 * The settings that carry a figure (the clerk limit, the floor, the cap, the terms and the late percent)
 * are dated: each value is recorded from a date (see {@link DatedSettings}); the policy date and the
 * period numbering from are not. */
@Service
public class SettingsService {

    private static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final SheetRoleRepository roles;
    private final SheetSettingRepository settings;
    private final DatedSettings dated;
    private final RollupService rollup;
    private final Audit audit;

    public SettingsService(SheetRepository sheets, SheetRoleRepository roles, SheetSettingRepository settings,
            DatedSettings dated, RollupService rollup, Audit audit) {
        this.sheets = sheets;
        this.roles = roles;
        this.settings = settings;
        this.dated = dated;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The roles given on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUser(sheetId);
    }

    /** The user's role on the sheet: a clerk unless made something else. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    @Transactional
    public SheetRole setRole(String sheetId, String by, String user, Role role) {
        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
        SheetRole given = roles.findBySheetIdAndUser(sheetId, user).orElse(null);
        if (given == null) {
            given = roles.saveAndFlush(new SheetRole(sheetId, user, role));
        } else {
            given.setRole(role);
            roles.flush();
        }
        audit.change("ROLE_SET", sheetId, by, "user=" + user, "role=" + role.name().toLowerCase());
        return given;
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return dated.clerkLimit(sheetId);
    }

    /** Record the sheet's clerk limit from {@code from} (the sheet's today when null); null records no limit. */
    @Transactional
    public void setClerkLimit(String sheetId, String by, BigDecimal limit, LocalDate from) {
        record(sheetId, by, DatedSettings.CLERK_LIMIT, limit == null ? null : limit.toPlainString(), from, false);
    }

    /** The floor in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return dated.floorOn(sheetId, today(sheetId));
    }

    /** Record the sheet's floor from {@code from} (the sheet's today when null); the live dues of the
     * claims dated from then, and so the figures, follow it. */
    @Transactional
    public void setFloor(String sheetId, String by, BigDecimal floor, LocalDate from) {
        record(sheetId, by, DatedSettings.FLOOR, floor.toPlainString(), from, true);
    }

    /** The cap in force on the sheet's today, the most a person's due-total can be; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String sheetId) {
        return dated.cap(sheetId);
    }

    /** Record the sheet's cap from {@code from} (the sheet's today when null); null records no cap. The
     * due-totals, and so the figures, follow the cap in force on the sheet's today. */
    @Transactional
    public void setCap(String sheetId, String by, BigDecimal cap, LocalDate from) {
        record(sheetId, by, DatedSettings.CAP, cap == null ? null : cap.toPlainString(), from, true);
    }

    /** The sheet's terms in force on its today, in days. */
    @Transactional(readOnly = true)
    public int terms(String sheetId) {
        return dated.termsOn(sheetId, today(sheetId));
    }

    /** Record the sheet's terms from {@code from} (the sheet's today when null); only the claims added
     * from then on, dated on or after it, of a person whose grade has no terms of its own then, are due
     * by them. */
    @Transactional
    public void setTerms(String sheetId, String by, int terms, LocalDate from) {
        record(sheetId, by, DatedSettings.TERMS, String.valueOf(terms), from, false);
    }

    /** The grades with their own terms in force on the sheet's today, by grade, in days. */
    @Transactional(readOnly = true)
    public Map<String, Integer> gradeTerms(String sheetId) {
        LocalDate today = today(sheetId);
        Map<String, Integer> terms = new LinkedHashMap<>();
        for (String grade : GRADES) {
            Integer own = dated.gradeTermsOn(sheetId, grade, today);
            if (own != null) terms.put(grade, own);
        }
        return terms;
    }

    /** The terms a claim dated {@code date} of a person of {@code grade} is due by (see {@link DatedSettings#termsFor}). */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return dated.termsFor(sheetId, grade, date);
    }

    /** Record the grade's own terms from {@code from} (the sheet's today when null); null records that
     * the grade uses the sheet's terms from then. Only the claims added from then on are due by them. */
    @Transactional
    public void setGradeTerms(String sheetId, String by, String grade, Integer terms, LocalDate from) {
        record(sheetId, by, DatedSettings.gradeTermsKey(grade), terms == null ? null : String.valueOf(terms), from,
                false);
    }

    /** The late percent in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String sheetId) {
        return dated.latePctOn(sheetId, today(sheetId));
    }

    /** Record the sheet's late percent from {@code from} (the sheet's today when null); the late charges
     * of the claims dated from then, and so the figures, follow it. */
    @Transactional
    public void setLatePct(String sheetId, String by, BigDecimal latePct, LocalDate from) {
        record(sheetId, by, DatedSettings.LATE_PCT, latePct.toPlainString(), from, true);
    }

    /** Every value recorded for the dated setting {@code key}, oldest from-date first. */
    @Transactional(readOnly = true)
    public List<SheetSetting> history(String sheetId, String key) {
        return dated.history(sheetId, key);
    }

    /** Record {@code value} for the dated setting {@code key} from {@code from} (the sheet's today when
     * null), keeping the values already recorded; one already recorded from that date is replaced. The
     * SETTING_CHANGED line ends with the from-date when one was given; when {@code figures} the ROLLUP
     * and TOTALS lines follow it. */
    private void record(String sheetId, String by, String key, String value, LocalDate from, boolean figures) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        RollupService.Snapshot before = figures ? rollup.snapshot(sheetId) : null;
        LocalDate on = from == null ? sheet.getToday() : from;
        SheetSetting recorded = settings.findBySheetIdAndKeyAndFrom(sheetId, key, on).orElse(null);
        if (recorded == null) {
            settings.save(new SheetSetting(sheetId, key, on, value));
        } else {
            recorded.setValue(value);
        }
        settings.flush();
        List<String> fields = new ArrayList<>(List.of("key=" + key, "value=" + (value == null ? "" : value)));
        if (from != null) fields.add("from=" + from);
        audit.change("SETTING_CHANGED", sheetId, by, fields.toArray(String[]::new));
        if (figures) rollup.recordSince(sheetId, by, before);
    }

    private LocalDate today(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
    }

    /** The sheet's policy date as set; null when it is the sheet's today. */
    @Transactional(readOnly = true)
    public LocalDate policyDate(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getPolicyDate();
    }

    /** Set the sheet's policy date; null makes it the sheet's today. The live figures' rounding follows it. */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String by, LocalDate policyDate) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        sheets.flush();
        audit.change("SETTING_CHANGED", sheetId, by, "key=policy-date",
                "value=" + (policyDate == null ? "" : policyDate.toString()));
        rollup.recordSince(sheetId, by, before);
        return sheet;
    }

    /** The sheet's period numbering from; null when it is off. */
    @Transactional(readOnly = true)
    public LocalDate periodNumberingFrom(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getPeriodNumberingFrom();
    }

    /** Set the sheet's period numbering from; null turns it off. Only the claims opened from then on follow it. */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String by, LocalDate from) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        sheet.setPeriodNumberingFrom(from);
        sheets.flush();
        audit.change("SETTING_CHANGED", sheetId, by, "key=period-numbering-from",
                "value=" + (from == null ? "" : from.toString()));
        return sheet;
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The values in force of a sheet's dated settings: on a date, the value recorded with the latest
 * from-date on or before it, and before every from-date the sheet's starting value (floor 1.00, late
 * percent 0.00, terms 14 days; no clerk limit, no cap, and no grade's own terms). A claim's floor, late
 * percent and terms are those in force on its date; the clerk limit and the cap those on the sheet's
 * today. */
@Service
public class DatedSettings {

    public static final String FLOOR = "floor";
    public static final String LATE_PCT = "late-pct";
    public static final String TERMS = "terms";
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";

    public static final BigDecimal FLOOR_START = new BigDecimal("1.00");
    public static final BigDecimal LATE_PCT_START = new BigDecimal("0.00");
    public static final int TERMS_START = 14;

    private final SheetSettingRepository settings;
    private final SheetRepository sheets;

    public DatedSettings(SheetSettingRepository settings, SheetRepository sheets) {
        this.settings = settings;
        this.sheets = sheets;
    }

    /** The key a grade's own terms are kept under. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** Every value recorded for the key, oldest from-date first. */
    @Transactional(readOnly = true)
    public List<SheetSetting> history(String sheetId, String key) {
        return settings.findBySheetIdAndKeyOrderByFromAsc(sheetId, key);
    }

    @Transactional(readOnly = true)
    public BigDecimal floorOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, FLOOR, date).map(BigDecimal::new).orElse(FLOOR_START);
    }

    @Transactional(readOnly = true)
    public BigDecimal latePctOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, LATE_PCT, date).map(BigDecimal::new).orElse(LATE_PCT_START);
    }

    /** The sheet's own terms in force on the date, in days. */
    @Transactional(readOnly = true)
    public int termsOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, TERMS, date).map(Integer::valueOf).orElse(TERMS_START);
    }

    /** The grade's own terms in force on the date, in days; null when it uses the sheet's terms then. */
    @Transactional(readOnly = true)
    public Integer gradeTermsOn(String sheetId, String grade, LocalDate date) {
        return valueOn(sheetId, gradeTermsKey(grade), date).map(Integer::valueOf).orElse(null);
    }

    /** The terms a claim dated {@code date} of a person of {@code grade} is due by: the grade's own in
     * force then, or else the sheet's in force then. */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(sheetId, grade, date);
        return own != null ? own : termsOn(sheetId, date);
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return valueOn(sheetId, CLERK_LIMIT, today(sheetId)).map(BigDecimal::new).orElse(null);
    }

    /** The cap in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String sheetId) {
        return valueOn(sheetId, CAP, today(sheetId)).map(BigDecimal::new).orElse(null);
    }

    /** The value of the key in force on the date; empty when none is recorded then, or the one
     * recorded is "none". */
    private Optional<String> valueOn(String sheetId, String key, LocalDate date) {
        return settings.findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(sheetId, key, date)
                .map(SheetSetting::getValue);
    }

    private LocalDate today(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
    }
}
package net.officefloor.hq.app.settings;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** The role a user name has been given on a sheet. */
@Entity
@Table(name = "sheet_role")
public class SheetRole {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String user;

    @Enumerated(EnumType.STRING)
    @Column(name = "role", nullable = false)
    private Role role;

    protected SheetRole() {
    }

    public SheetRole(String sheetId, String user, Role role) {
        this.sheetId = sheetId;
        this.user = user;
        this.role = role;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUser() {
        return user;
    }

    public Role getRole() {
        return role;
    }

    public void setRole(Role role) {
        this.role = role;
