import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates, by grade, then by from-date (one with none first). */
    @Query("SELECT r FROM Rate r WHERE r.sheetId = :sheetId ORDER BY r.grade ASC, r.from ASC NULLS FIRST")
    List<Rate> findBySheetIdOrderByGradeAndFrom(String sheetId);

    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    @Query("SELECT r FROM Rate r WHERE r.sheetId = :sheetId AND r.grade = :grade AND r.from IS NULL")
    Optional<Rate> findUndated(String sheetId, String grade);

    Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate from);

    /** The grade's rate in force on {@code date}: the one with the latest from-date on or before it, or
     * the one with no from-date when none has; empty when no rate applies yet, or when that rate's
     * to-date is before {@code date} (an earlier rate does not apply again). */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> r.getFrom() == null || !r.getFrom().isAfter(date))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.getTo() == null || !r.getTo().isBefore(date));
    }
}
package net.officefloor.hq.app.paste;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Adds a DRAFT claim per pasted line of {@code name,amount,date,note}, in order, for the person on the
 * sheet with that name (compared as names are). The date may be blank (the sheet's today); the note may
 * hold commas, or be left out. Each line is held to the claim form's rules; it is one change: when any
 * line is refused no claim is added, and nothing is recorded. Blank lines are skipped. */
@Service
public class PasteService {

    /** An amount as the claim form takes it. */
    private static final Pattern AMOUNT = Pattern.compile("\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*");

    /** The longest note the claim form takes. */
    private static final int NOTE_MAX = 500;

    private final PersonRepository people;
    private final ClaimService claimService;

    public PasteService(PersonRepository people, ClaimService claimService) {
        this.people = people;
        this.claimService = claimService;
    }

    /** The claims added, in the order of their lines. */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Claim> added = new ArrayList<>();
        for (String line : text.split("\\r?\\n")) {
            if (line.isBlank()) continue;
            String[] fields = line.split(",", 4);
            if (fields.length < 2 || fields[0].isBlank() || !AMOUNT.matcher(fields[1]).matches()) {
                throw new PasteLineException();
            }
            Person person = people.findBySheetIdAndNameKey(sheetId, Person.keyOf(fields[0]))
                    .orElseThrow(PersonNotFoundException::new);
            String note = fields.length > 3 ? fields[3].trim() : "";
            if (note.length() > NOTE_MAX) throw new PasteLineException();
            BigDecimal amount = new BigDecimal(fields[1].trim()).setScale(2);
            added.add(claimService.add(sheetId, user, person.getId(), amount, dateOf(fields), note, null));
        }
        if (added.isEmpty()) throw new PasteLineException();
        return added;
    }

    /** The line's date; null when it is blank or left out. */
    private static LocalDate dateOf(String[] fields) {
        if (fields.length < 3 || fields[2].isBlank()) return null;
        try {
            return LocalDate.parse(fields[2].trim());
        } catch (DateTimeParseException e) {
            throw new PasteLineException();
        }
    }
}
package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Adds a DRAFT claim, dated the sheet's today with an empty note, for a person named on the sheet,
 * first adding them with grade A when no one has that name. It is one change: when the claim is
 * refused the person is not added either, and nothing is recorded. */
@Service
public class QuickAddService {

    /** The grade a person added by a quick-add is given. */
    static final String GRADE = "A";

    public record Added(Person person, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
